/** The label of a template's install action: an agent is added to the user's agents. */
 export const getInstallLabel = (
 t: (key: string) => string,
 template: TAiTemplate,
 ) =>
 template.kind === "agent" ? t("Common:AddToMyAgents") : t("Common:Install");

